package com.aicharacter.v3;import java.util.*;
public final class CatSleepPlanner{public static final class Plan{public final String mode,areaId,targetEntity;public final double score;public final String reason;Plan(String m,String a,String t,double s,String r){mode=m;areaId=a;targetEntity=t;score=s;reason=r;}}private CatSleepPlanner(){}
 public static List<Plan> candidates(WorldState s){CatState c=s.catState;List<Plan>out=new ArrayList<>();String from=areaIdAt(s,c.x);double tired=Math.max(c.sleepiness/100.0,(100-c.energy)/100.0);boolean bad="RAIN".equals(s.environment.weather);double hc=WorldPathPlanner.routeCost(s,"cat",from,"home_shelter");if(Double.isFinite(hc))out.add(new Plan("HOME","home_shelter","shelter_01",1.05-hc/2600+(bad?.25:0)+tired*.12,"reachable home route cost="+(int)hc));if(tired>.70||hc>700){WorldArea here=s.world.area(from);if(here!=null)out.add(new Plan("SAFE_SPOT",from,"",.78+tired*.35+(bad?.18:0),"too tired/far to force home; remain at reachable local rest context"));}WorldObject safe=s.world.firstTagged("safe");if(safe!=null){double sc=WorldPathPlanner.routeCost(s,"cat",from,safe.areaId);if(Double.isFinite(sc))out.add(new Plan("SAFE_SPOT",safe.areaId,safe.id,.72-sc/2100+(bad?.28:0)+tired*.20,"safe route cost="+(int)sc));}String ga=areaIdAt(s,s.haruX);CatSocialState social=s.catSocial==null?new CatSocialState():s.catSocial;double gc=WorldPathPlanner.routeCost(s,"cat",from,ga),comfort=Math.max(0,Math.min(1,social.comfort)),trust=Math.max(0,Math.min(1,social.familiarity*(1-social.wariness*.55)));if(Double.isFinite(gc)&&gc<1200){out.add(new Plan("NEAR_GIRL",ga,"",.5+comfort*.25-gc/2400,"reachable girl area cost="+(int)gc));if(trust>.16&&comfort>.16)out.add(new Plan("WITH_GIRL",ga,"girl",.52+trust*.28+comfort*.3+tired*.18-gc/2600,"carried context after reachable approach cost="+(int)gc));}out.sort((a,b)->Double.compare(b.score,a.score));return out;}
 public static Plan choose(WorldState s){List<Plan>c=candidates(s);if(!c.isEmpty())return c.get(0);String here=areaIdAt(s,s.catState.x);return new Plan("STRANDED",here,"",0,"no reachable sleep route or verified safe local context");}private static String areaIdAt(WorldState s,float x){WorldArea a=s.world.areaAt(x);if(a!=null)return a.id;String persisted=s.catState==null?"":s.catState.areaId;return persisted!=null&&s.world.area(persisted)!=null?persisted:"";}}
